#include "media.h"
#include "vga.h"
static u16 rd16(const u8*p){return (u16)(p[0]|((u16)p[1]<<8));}static u32 rd32(const u8*p){return (u32)p[0]|((u32)p[1]<<8)|((u32)p[2]<<16)|((u32)p[3]<<24);}
int bmp_draw(const u8*d,u32 sz,int cx,int cy,int cw,int ch){if(!d||sz<54||d[0]!='B'||d[1]!='M'||!vga_framebuffer())return 0;u32 off=rd32(d+10),dib=rd32(d+14);if(dib<40||off>=sz)return 0;i32 w=(i32)rd32(d+18),h=(i32)rd32(d+22);u16 planes=rd16(d+26),bpp=rd16(d+28);u32 comp=rd32(d+30);if(w<=0||h==0||planes!=1||comp!=0||(bpp!=24&&bpp!=32))return 0;int top=h<0;if(h<0)h=-h;u32 row=((u32)w*(bpp/8)+3)&~3u;if(off+row*(u32)h>sz)return 0;int x,y,tw,th;vga_cell_rect(cx,cy,cw,ch,&x,&y,&tw,&th);if(tw<=0||th<=0)return 0;vga_fill_px(x,y,tw,th,vga_rgb_bg());for(int yy=0;yy<th;yy++){int sy=(int)((u32)yy*(u32)h/(u32)th);if(!top)sy=h-1-sy;const u8*r=d+off+(u32)sy*row;for(int xx=0;xx<tw;xx++){int sx=(int)((u32)xx*(u32)w/(u32)tw);const u8*p=r+(u32)sx*(bpp/8);u32 rgb=((u32)p[2]<<16)|((u32)p[1]<<8)|p[0];vga_pixel(x+xx,y+yy,rgb);}}return 1;}
